    if (bookIdMatch && bookIdMatch[1]) {
        let bookId = bookIdMatch[1];
        let requestUrl = 'https://www.aiqu666.com/txt-xx/softdownfree.asp?softid=' + bookId + '&ckm=mianfei';
        let html = java.ajax(requestUrl);
        let downloadSection = html.match(/<img[^>]*icon_downloadserver[^>]*>([\s\S]*?)<span style="FONT-SIZE: 18px; COLOR: #0000ff">下载帮助:/);

        if (downloadSection) {
            let firstMatch = downloadSection[1].match(/第一下载地址[^<]*<a[^>]*href="([^"]+\.(txt|zip|rar|epub))"/);
            if (firstMatch && firstMatch[1]) {
                firstMatch[1];
            } else {
                let allLinks = downloadSection[1].match(/href="([^"]+\.(txt|zip|rar|epub))"/g);
                allLinks && allLinks.length > 1 ? allLinks[1].replace('href="', '').replace('"', '') : '';
            }
        } else {
            '';
        }
    } else {
        url;
    }
} else {
    url;
}

ruleBookInfo.intro:
&nbsp;&nbsp;
✨ 源站：{{$.source}}{{"\n"+"​"}}
{{$.desc}}
<js>
const tomatoSources = ["番茄小说", "番茄听书", "番茄畅听"];
const jjwxcSources = ["晋江"];

const sourceName = "{{$.source}}";
const bookIdFromBackend = "{{$.bookid}}";

let finalResult = result;

if (tomatoSources.includes(sourceName)) {
    try {
        let syncStatus = getConfig.call(this).book_sync || "off";
        let fqdownStatus = getConfig.call(this).fqdown || "off";
        let bookId = bookIdFromBackend;
        if (bookId) {
            let bookData = getBookData(bookId);

            if (bookData) {
                if (syncStatus == "on") {
                    syncReadingHistory(bookId);
                }

                let bookName = bookData.original_book_name || bookData.book_name || "";
                let aliasName = bookData.book_flight_alias_name || bookData.sub_title || "";
                let createTime = bookData.create_time ? bookData.create_time.split('T')[0] : (bookData.first_online_time ? java.timeFormat(parseInt(Object.values(JSON.parse(bookData.first_online_time))[0])*1000).split(' ')[0] : "");
                let updateTime = bookData.last_chapter_update_time ? java.timeFormat(parseInt(bookData.last_chapter_update_time)*1000) : "";

                let authorName = "";
                if (bookData.original_authors) {
                    try {
                        let authorsParsed = JSON.parse(bookData.original_authors);
                        authorName = Array.isArray(authorsParsed) ? authorsParsed.map(a => a.AuthorName || a.author_name || a).join(', ') : bookData.original_authors;
                    } catch(e) {
                        authorName = bookData.original_authors;
                    }
                } else {
                    authorName = bookData.author || "";
                }

                let roleName = "";
                if (bookData.roles) {
                    try {
                        let rolesParsed = JSON.parse(bookData.roles);
                        roleName = Array.isArray(rolesParsed) ? rolesParsed.join(', ') : bookData.roles;
                    } catch(e) {
                        roleName = bookData.roles;
                    }
                } else if (bookData.role) {
                    roleName = bookData.role;
                }

                let bookTagsData = bookData.pure_category_tags || bookData.tags || "";
                let readCount = bookData.read_count || "0";
                let bookStatus = bookData.book_search_visible == 'false' ? "下架" : "正常";
                let abstract = bookData.book_abstract_v2 || bookData.abstract || "";
                let copyrightInfo = bookData.copyright_info || "";

                let output = `&nbsp;&nbsp;
✨ 源站：${sourceName}{{"\n"+"​"}}
📕 源名：${bookName}`;

                if (aliasName) output += `\n📖 别名：${aliasName}`;

                if (sourceName == "番茄小说" && fqdownStatus == "on") {
                    output += `\n⚠️ 当前为TXT下载模式，在线阅读或换源请在登陆关闭后刷新详情页！`;
                }

                output += `\n✏️ 开坑：${createTime} 
🧭 更新：${updateTime}&lrm;
👤 作者：${authorName}`;

                if (roleName) output += `\n🎭 主角：${roleName}`;

                output += `
🏷️ 标签：${bookTagsData}
👁️ 在线：${readCount}人在读
🔗 书籍状态：${bookStatus} `;

                output += `\n🔄 阅读记录：${syncStatus == "on" ? "✅已开启同步" : "❌已关闭同步"}`;

                if (sourceName == "番茄听书" || sourceName == "番茄小说") {
                    try {
                        let ttsUrl = `https://reading.snssdk.com/reading/bookapi/audio/toneinfo/?book_id=${bookId}&aid=1967`;
                        let response = java.ajax(ttsUrl);
                        let data = JSON.parse(response);
                        let ttsData = data.data;

                        if (ttsData) {
                            let ttsTones = ttsData.tts_tones || [];
                            let audioTones = ttsData.audio_tones || [];
                            let recommendTone = ttsData.recommend_tone;

                            let rawAbookIds = [];
                            try {
                                let matches = response.match(/"abook_id"\s*:\s*(\d+)/g) || [];
                                for (var r = 0; r < matches.length; r++) {
                                    let idMatch = matches[r].match(/(\d+)/);
                                    if (idMatch) rawAbookIds.push(idMatch[1]);
                                }
                            } catch (e) {}

                            if (recommendTone) {
                                for (var i = 0; i < ttsTones.length; i++) {
                                    if (ttsTones[i].id == recommendTone) {
                                        output += '\n🎤 推荐音色：' + ttsTones[i].title + ' (音色ID: ' + ttsTones[i].id + ')';
                                        break;
                                    }
                                }
                            }

                            if (ttsTones.length > 0) {
                                var availableTones = '';
                                for (var j = 0; j < ttsTones.length; j++) {
                                    if (j > 0) availableTones += '、';
                                    availableTones += ttsTones[j].title + '(音色ID: ' + ttsTones[j].id + ')';
                                }
                                output += '\n🎧 可用音色：' + availableTones;
                            }

                            if (audioTones.length > 0) {
                                output += '\n🎙️ 真人主播：';
                                for (var m = 0; m < audioTones.length; m++) {
                                    var toneTitle = audioTones[m].title || '';
                                    var abookId = rawAbookIds[m] || String(audioTones[m].abook_id || '');
                                    output += '\n　　' + toneTitle + '（书籍ID: ' + abookId + '@番茄畅听）';
                                }
                            } else {
                                output += '\n🎙️ 真人主播：本书不支持真人主播';
                            }
                        }
                    } catch (e) {}
                }

                output += `{{"\n"+"​"}}
📜 简介：${abstract}{{"\n"+"​"}}`;

                if (copyrightInfo) {
                    output += `\n📍 ${copyrightInfo.split('，')[0]}。`;
                }

                finalResult = output;
            }
        }
    } catch (e) {
    }
} else if (jjwxcSources.some(source => sourceName.includes(source))) {
    try {
        let novelId = bookIdFromBackend;

        if (novelId) {
            let currentVariable = book.getVariable("custom") || "";

            if (!currentVariable.includes("开启段评") && !currentVariable.includes("关闭段评")) {
                try {
                    let checkUrl = `https://android.jjwxc.com/app.jjwxc/android/reading/authorNovelSetting/getSetting?versionCode=381&novelid=${novelId}&setting_type=author_paragraph_comment_switch`;

                    let request = `${checkUrl},${JSON.stringify({
                        headers: {
                            "versiontype": "reading",
                            "versionCode": "381"
                        }
                    })}`;

                    let ajaxResult = java.ajax(request);
                    let checkResponse = JSON.parse(ajaxResult);

                    let paraEnabled = checkResponse.data?.paragraph_switch == "1";

                    let newVariable = currentVariable + (paraEnabled ? "开启段评" : "关闭段评");
                    book.putVariable("custom", newVariable);

                } catch(e) {
                    let newVariable = currentVariable + "关闭段评";
                    book.putVariable("custom", newVariable);
                }
            }
        }
    } catch (e) {
    }
}
finalResult;
</js>

