                    "番茄畅听": "/fq_comment?book_id=" + bookid,
                    "番茄漫画": "/fq_comment?book_id=" + bookid
                };

                if (urlMap[source]) {
                    targetUrl = getServerHost() + urlMap[source];
                }
            }
        } catch (e) {}
    }

    if (targetUrl) {
        targetUrl += "&key=" + getSecretKey();
        java.showBrowser(
